using System.Collections;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

// World-space VR main menu: NEW GAME / CONTINUE / SETTINGS / EXIT.
// The hierarchy is generated by Assets/Editor/BuildMainMenu.cs.
public class MainMenu : MonoBehaviour
{
    [Header("Panels")]
    public GameObject menuRoot;
    public GameObject loadingPanel;
    public GameObject settingsPanel;

    [Header("Loading")]
    public Image loadingFill;
    public TMP_Text loadingPercent;
    public float loadingSeconds = 2.5f;

    [Header("Settings")]
    public Slider volumeSlider;
    public TMP_Text volumeValue;
    public Slider brightnessSlider;
    public TMP_Text brightnessValue;
    public Image highButton;
    public Image ultraButton;

    float baseAmbient;
    Coroutine loadingRoutine;

    static readonly Color Cyan = new Color(0f, 0.898f, 1f, 1f);
    static readonly Color Off = new Color(1f, 1f, 1f, 0.06f);

    void Awake()
    {
        var canvas = GetComponentInChildren<Canvas>(true);
        if (canvas != null && canvas.worldCamera == null) canvas.worldCamera = Camera.main;
        baseAmbient = RenderSettings.ambientIntensity;
    }

    void Start()
    {
        loadingPanel.SetActive(false);
        settingsPanel.SetActive(false);
        volumeSlider.SetValueWithoutNotify(Mathf.Round(AudioListener.volume * 100f));
        brightnessSlider.SetValueWithoutNotify(62f);
        volumeSlider.onValueChanged.AddListener(OnVolume);
        brightnessSlider.onValueChanged.AddListener(OnBrightness);
        OnVolume(volumeSlider.value);
        OnBrightness(brightnessSlider.value);
        SetGraphics(QualitySettings.names.Length > 1 && QualitySettings.GetQualityLevel() < QualitySettings.names.Length - 1 ? 0 : 1);
    }

    public void NewGame()
    {
        if (loadingRoutine == null) loadingRoutine = StartCoroutine(LoadingRoutine());
    }

    public void OpenSettings() { settingsPanel.SetActive(true); }
    public void CloseSettings() { settingsPanel.SetActive(false); }

    public void ExitGame()
    {
#if UNITY_EDITOR
        UnityEditor.EditorApplication.isPlaying = false;
#else
        Application.Quit();
#endif
    }

    public void SetHigh() { SetGraphics(0); }
    public void SetUltra() { SetGraphics(1); }

    public void SetGraphics(int index)
    {
        // 0 = HIGH, 1 = ULTRA
        int last = QualitySettings.names.Length - 1;
        QualitySettings.SetQualityLevel(index == 1 ? last : Mathf.Max(0, last - 1), true);
        if (highButton != null) highButton.color = index == 0 ? Color.white : Off;
        if (ultraButton != null) ultraButton.color = index == 1 ? Color.white : Off;
    }

    void OnVolume(float v)
    {
        AudioListener.volume = v / 100f;
        volumeValue.text = Mathf.RoundToInt(v) + "%";
    }

    void OnBrightness(float v)
    {
        RenderSettings.ambientIntensity = baseAmbient * Mathf.Lerp(0.3f, 1.7f, v / 100f);
        brightnessValue.text = Mathf.RoundToInt(v) + "%";
    }

    IEnumerator LoadingRoutine()
    {
        loadingPanel.SetActive(true);
        float t = 0f;
        while (t < loadingSeconds)
        {
            t += Time.unscaledDeltaTime;
            float p = Mathf.Clamp01(t / loadingSeconds);
            loadingFill.fillAmount = p;
            loadingPercent.text = Mathf.RoundToInt(p * 100f) + "%";
            yield return null;
        }
        yield return new WaitForSecondsRealtime(0.6f);
        menuRoot.SetActive(false);
        if (GameAudio.Instance != null) GameAudio.Instance.StartLoops();
        loadingRoutine = null;
    }
}
